function validate([corridor]) {
  if (typeof corridor !== 'string' || corridor.length < 1 || corridor.length > 100000) return 'corridor has 1 to 10^5 characters.';
  if (!/^[SP]+$/.test(corridor)) return "corridor uses only 'S' and 'P'.";
  return null;
}

