function numberOfWays(corridor) {
  const MOD = 1000000007;
  let ways = 1;
  let seats = 0;
  let lastSeat = -1;

  for (let i = 0; i < corridor.length; i++) {
    if (corridor[i] !== 'S') {
      continue;
    }
    seats += 1;
    if (seats > 2 && seats % 2 === 1) {
      ways = (ways * (i - lastSeat)) % MOD;
    }
    lastSeat = i;
  }

  if (seats === 0 || seats % 2 === 1) {
    return 0;
  }
  return ways;
}

