function numberOfWays(corridor) {
  // Scan left to right, tracking how many layouts leave the open room with 0, 1 or 2 seats.
  const MOD = 1000000007;
  let open = [1, 0, 0];
  for (let i = 0; i < corridor.length; i++) {
    // A wall in the gap before spot i may close a room only when it already has two seats.
    if (i > 0) open = [(open[0] + open[2]) % MOD, open[1], open[2]];
    // A seat moves every layout up one seat; a third seat would break the room.
    if (corridor[i] === 'S') open = [0, open[0], open[1]];
  }
  return open[2];
}

