function generate(rand, size) {
  const n = size === 'large' ? 10000 - Math.floor(rand() * 50) : 1 + Math.floor(rand() * 14);
  const density = rand() < 0.1 ? 0 : 0.05 + rand() * 0.8;
  const spots = Array.from({ length: n }, () => (rand() < density ? 'S' : 'P'));
  let seats = spots.filter(c => c === 'S').length;
  // Mostly keep an even seat count so the answer is usually non-zero.
  if (seats % 2 === 1 && rand() < 0.8) {
    const at = spots.lastIndexOf('S');
    spots[at] = 'P';
    seats -= 1;
  }
  return [spots.join('')];
}
